-- Partner deals (seeded from seed/deals.sql, regenerated by scripts/import_deals.py)
CREATE TABLE deals (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  subtitle    TEXT NOT NULL DEFAULT '',
  category    TEXT NOT NULL,            -- food | lodging | transport | shopping | services | entertainment | health | education
  regions     TEXT NOT NULL DEFAULT '', -- comma list: north,central,south,east
  highlight   TEXT NOT NULL DEFAULT '', -- short badge shown publicly, e.g. 9折
  offer       TEXT NOT NULL DEFAULT '', -- full terms (login required)
  info        TEXT NOT NULL DEFAULT '', -- merchant info (login required)
  phone       TEXT NOT NULL DEFAULT '',
  address     TEXT NOT NULL DEFAULT '',
  links       TEXT NOT NULL DEFAULT '[]', -- JSON [{label,url}]
  expires_on  TEXT,                     -- YYYY-MM-DD or NULL
  auto_renew  INTEGER NOT NULL DEFAULT 0,
  notes       TEXT NOT NULL DEFAULT '',
  eligibility TEXT NOT NULL DEFAULT '{}', -- JSON {student,staff,alumni,family}
  schools      TEXT NOT NULL DEFAULT 'NTU', -- comma list of school codes the deal applies to
  source_level TEXT NOT NULL DEFAULT 'school', -- school | college | department | student_org | merchant | platform
  source_org   TEXT NOT NULL DEFAULT '',      -- publisher, e.g. 臺大財務管理處
  source_url   TEXT NOT NULL DEFAULT '',
  retrieved_on TEXT,                          -- when the source was last checked
  sort_order   INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX deals_category ON deals(category);

-- Everyone who has signed in with Google
CREATE TABLE users (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  google_sub     TEXT NOT NULL UNIQUE,
  email          TEXT NOT NULL,
  email_verified INTEGER NOT NULL DEFAULT 0,
  email_domain   TEXT NOT NULL DEFAULT '',
  name           TEXT NOT NULL DEFAULT '',
  picture        TEXT NOT NULL DEFAULT '',
  created_at     TEXT NOT NULL DEFAULT (datetime('now')),
  last_login_at  TEXT NOT NULL DEFAULT (datetime('now')),
  login_count    INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX users_email ON users(email);

CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at TEXT NOT NULL
);
CREATE INDEX sessions_user ON sessions(user_id);

CREATE TABLE favorites (
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  deal_id    TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (user_id, deal_id)
);

-- Usage signal: which deals signed-in users open
CREATE TABLE deal_views (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id    INTEGER NOT NULL,
  deal_id    TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX deal_views_deal ON deal_views(deal_id);

-- "This deal is wrong / expired" reports, reviewed manually
CREATE TABLE reports (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id    INTEGER NOT NULL,
  deal_id    TEXT NOT NULL,
  message    TEXT NOT NULL,
  status     TEXT NOT NULL DEFAULT 'open',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
